
(()=>{
const C=window.IDP_CORE, P=window.IDP_POSTS, Q=window.IDP_POETRY, R=window.IDP_READER_IMPACT||{entries:[],methodology:''}, M=window.IDP_MEDIA_CATALOG||{stats:{},assets:[],collections:[]}, Y=window.IDP_YOUTUBE_MEDIA||{channel:{},relevantVideos:[],stats:{}}, CM=window.IDP_CREATIVE_META||{works:{},seeds:[],completion:{},provenance:{},confidence:{}}, V=window.IDP_VERSION_HISTORY||{current:'unknown',releases:[],milestones:[]}, CFG=window.IDP_CONFIG||{};
const app=document.getElementById('app');
const forumById=new Map(C.forums.map(x=>[x.id,x])), topicById=new Map(C.topics.map(x=>[x.id,x])), userById=new Map(C.users.map(x=>[x.id,x])), postById=new Map(P.map(x=>[x.id,x]));
const postsByTopic=new Map(), postsByUser=new Map(), topicsByForum=new Map(), worksByUser=new Map();
for(const p of P){if(!postsByTopic.has(p.t))postsByTopic.set(p.t,[]);postsByTopic.get(p.t).push(p);if(!postsByUser.has(p.u))postsByUser.set(p.u,[]);postsByUser.get(p.u).push(p)}
for(const t of C.topics){if(!topicsByForum.has(t.f))topicsByForum.set(t.f,[]);topicsByForum.get(t.f).push(t)}
for(const w of Q.works){const k=(w.u||'').toLowerCase();if(!worksByUser.has(k))worksByUser.set(k,[]);worksByUser.get(k).push(w)}
const n=x=>Number(x||0).toLocaleString();
let textDisplayMode=localStorage.getItem('idpTextDisplay')||'original';
const mojibakePairs=[['â€™','’'],['â€˜','‘'],['â€œ','“'],['â€','”'],['â€“','–'],['â€”','—'],['â€¦','…'],['â€¢','•'],['Â ',' '],['Ã©','é'],['Ã¨','è'],['Ã¡','á'],['Ã³','ó'],['Ã¶','ö'],['Ã¼','ü'],['Ã±','ñ'],['Ã§','ç'],['Ã¢','â'],['Ãª','ê'],['Ã®','î'],['Ã´','ô'],['Ã»','û'],['Ã£','ã'],['Ãµ','õ'],['Ã¥','å'],['Ã¸','ø'],['Ã¦','æ'],['Ã‰','É']];
function repairMojibake(value){let out=String(value??'');for(const [bad,good] of mojibakePairs)out=out.split(bad).join(good);return out}
function displayText(value){return textDisplayMode==='repair'?repairMojibake(value):String(value??'')}
const esc=s=>displayText(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function workMeta(w){return (CM.works&&CM.works[String(w.id)])||{}}

function metaName(group,key){return key&&CM[group]&&CM[group][key]?CM[group][key].label:''}

function metaBadges(m){const bits=[];const st=metaName('completion',m.status),pr=metaName('provenance',m.provenance);if(st)bits.push(`<span class="meta-badge status-${esc(m.status)}">${esc(st)}</span>`);if(pr)bits.push(`<span class="meta-badge provenance-${esc(m.provenance)}">${esc(pr)}</span>`);if(m.confidence&&CM.confidence&&CM.confidence[m.confidence])bits.push(`<span class="meta-badge confidence">${esc(CM.confidence[m.confidence])}</span>`);return bits.length?`<div class="meta-badges">${bits.join('')}</div>`:''}

function seedEntries(){const statuses=['seed','growing','candidate','graduated'];const out=(CM.seeds||[]).map((x,i)=>({...x,_key:x.id||`seed-${i+1}`}));const seenWork=new Set(out.filter(x=>x.workId!=null).map(x=>String(x.workId))),seenIds=new Set(out.map(x=>String(x.id||x._key)));for(const w of Q.works){const m=workMeta(w);if(statuses.includes(m.status)&&!seenWork.has(String(w.id))){out.push({...m,_key:`work-${w.id}`,workId:w.id,title:w.title,text:w.x,date:w.d,source:w.forum||w.type});seenWork.add(String(w.id))}}for(const x of supplementalWorks()){if(statuses.includes(x.status)&&!seenIds.has(String(x.id))){out.push({...x,_key:x.id,creativeId:x.id});seenIds.add(String(x.id))}}return out}

function supplementalWorks(){return Array.isArray(CM.supplementalWorks)?CM.supplementalWorks:[]}

function supplementalById(id){return supplementalWorks().find(x=>String(x.id)===String(id))}

function archiveDocuments(){return Array.isArray(CM.archiveDocuments)?CM.archiveDocuments:[]}

function archiveDocumentById(id){return archiveDocuments().find(x=>String(x.id)===String(id))}

function verificationCandidates(){return Array.isArray(CM.verificationCandidates)?CM.verificationCandidates:[]}
const VERIFY_KEY='idpVerificationV1';
function readVerification(){try{const x=JSON.parse(localStorage.getItem(VERIFY_KEY)||'{}');return x&&typeof x==='object'?x:{}}catch(e){return {}}}
function writeVerification(x){localStorage.setItem(VERIFY_KEY,JSON.stringify(x))}
function candidateDecision(x,state){const d=state[x.id]||{};return {authorshipValue:Number.isFinite(Number(d.authorshipValue))?Number(d.authorshipValue):Number(x.authorshipValue||0),completionValue:Number.isFinite(Number(d.completionValue))?Number(d.completionValue):Number(x.completionValue||0),confidenceValue:Number.isFinite(Number(d.confidenceValue))?Number(d.confidenceValue):Number(x.confidenceValue||0),verifiedAt:d.verifiedAt||''}}
function authorshipLabel(v){const x=CM.verificationScale&&CM.verificationScale.authorship&&CM.verificationScale.authorship[String(v)];return x?x.label:(v===1?'Mine':v===-1?'Not Mine':'Unsure')}
function completionLabel(v){const x=CM.verificationScale&&CM.verificationScale.completion&&CM.verificationScale.completion[String(v)];return x?x.label:(v===3?'Finished':v===2?'Growing':v===1?'Seed':'Unsure')}
function confidenceLabel(v){return CM.verificationScale&&CM.verificationScale.confidence&&CM.verificationScale.confidence[String(v)]||'Uncertain'}

function supplementalRow(x){return `<div class="row"><div><a href="#creative/${encodeURIComponent(x.id)}">${esc(x.title||'Untitled')}</a><div class="sub">${esc(x.source||'reconciled creative record')}</div>${metaBadges(x)}</div><div class="counts">${esc(x.confidence&&CM.confidence&&CM.confidence[x.confidence]?CM.confidence[x.confidence]:'')}</div></div>`}

function documentRow(x){return `<div class="row"><div><a href="#document/${encodeURIComponent(x.id)}">${esc(x.title||'Untitled document')}</a><div class="sub">${esc(x.type||'archive document')}${x.date?` • ${esc(x.date)}`:''}</div>${x.source?`<div class="small">${esc(x.source)}</div>`:''}</div><div class="counts">${esc(x.confidence&&CM.confidence&&CM.confidence[x.confidence]?CM.confidence[x.confidence]:'')}</div></div>`}

function provenanceMap(m){if(!Array.isArray(m.segments)||!m.segments.length)return '';return sectionHead('Authorship map','Section-level provenance where the surviving evidence supports it')+`<div class="work-list provenance-map">${m.segments.map(seg=>`<div class="row"><div><strong>${esc(seg.label||'Section')}</strong>${seg.range?`<div class="sub">${esc(seg.range)}</div>`:''}${seg.notes?`<div class="small">${esc(seg.notes)}</div>`:''}</div><div>${metaBadges({provenance:seg.provenance,confidence:seg.confidence})}</div></div>`).join('')}</div>`}

function safeDec(v){v=String(v??'');try{return decodeURIComponent(v)}catch(e){try{return decodeURIComponent(v.replace(/%(?![0-9a-fA-F]{2})/g,'%25'))}catch(e2){return v}}}

function hashParams(){const h=location.hash||'';const i=h.indexOf('?');try{return new URLSearchParams(i<0?'':h.slice(i+1))}catch(e){return new URLSearchParams()}}

function pageNum(v,pages){let x=parseInt(String(v??'').trim(),10);if(!Number.isFinite(x)||x<1)x=1;return Math.min(x,Math.max(1,pages))}

function qs(base,obj){const u=new URLSearchParams();for(const[k,v]of Object.entries(obj))if(v!==''&&v!=null)u.set(k,String(v));const t=u.toString();return base+(t?'?'+t:'')}

function paginate(arr,per,raw){const pages=Math.max(1,Math.ceil(arr.length/per));const page=pageNum(raw,pages);return {page,pages,per,total:arr.length,items:arr.slice((page-1)*per,page*per)}}

function pagerNav(href,pg,label){const {page,pages,per,total}=pg;const a=total?(page-1)*per+1:0,b=Math.min(total,page*per);let out=`<div class="pager-info small" role="status">Showing ${n(a)}–${n(b)} of ${n(total)} ${esc(label)}${pages>1?` • page ${n(page)} of ${n(pages)}`:''}</div>`;if(pages<=1)return out;out+=`<nav class="pagination" aria-label="${esc(label)} pages">`;out+=page>1?`<a href="${esc(href(page-1))}" rel="prev" aria-label="Previous page">‹ Prev</a>`:`<span class="disabled" aria-disabled="true">‹ Prev</span>`;for(let i=1;i<=pages;i++){if(i===1||i===pages||Math.abs(i-page)<=2)out+=`<a class="${i===page?'current':''}" href="${esc(href(i))}"${i===page?' aria-current="page"':''} aria-label="Page ${i}">${i}</a>`;else if(i===page-3||i===page+3)out+='<span aria-hidden="true">…</span>'}out+=page<pages?`<a href="${esc(href(page+1))}" rel="next" aria-label="Next page">Next ›</a>`:`<span class="disabled" aria-disabled="true">Next ›</span>`;return out+'</nav>'}

function seedRelatedLinks(x){const ids=Array.isArray(x.related)?x.related:[];const links=ids.map(id=>{const y=supplementalById(id);return y?`<a href="#creative/${encodeURIComponent(y.id)}">${esc(y.title||id)}</a>`:''}).filter(Boolean);return links.length?`<div class="seed-related small"><strong>Later growth:</strong> ${links.join(' • ')}</div>`:''}

function seedRow(x){const id='seed-'+String(x._key||x.id||x.workId||'item').replace(/[^a-z0-9_-]/gi,'-');const href=x.workId!=null?`#poem/${x.workId}`:x.creativeId?`#creative/${encodeURIComponent(x.creativeId)}`:'';return `<div class="row seed-row" id="${esc(id)}"><div>${href?`<a href="${href}">${esc(x.title||'Untitled seed')}</a>`:`<strong>${esc(x.title||'Untitled seed')}</strong>`}<div class="sub">${esc(x.source||'source under review')}${x.date?` • ${fmtDate(x.date)}`:''}</div>${metaBadges(x)}${seedRelatedLinks(x)}${x.text?`<details><summary>Read seed</summary><pre class="poem-text seed-text">${esc(x.text)}</pre></details>`:''}${x.notes?`<p class="small">${esc(x.notes)}</p>`:''}</div></div>`}

function seeds(){const items=seedEntries();const counts={seed:0,growing:0,candidate:0,graduated:0};for(const x of items)if(counts[x.status]!=null)counts[x.status]++;const legend=`<div class="grid seed-legend"><div class="card"><h3>Seed</h3><p>Incomplete fragment, idea, stanza, phrase, or partial work.</p></div><div class="card"><h3>Growing</h3><p>A substantial draft still being developed.</p></div><div class="card"><h3>Seed Candidate</h3><p>Possibly unfinished, but not classified without stronger evidence.</p></div><div class="card"><h3>Graduated Seed</h3><p>A Seed that later became a finished work; its early state remains part of the lineage.</p></div></div>`;return `${pageTitle('Creative development','Seeds','The in-progress side of the archive: fragments, drafts, and incomplete works. Completion status and authorship provenance are tracked separately.')}<div class="stats">${stat(counts.seed,'Seeds')}${stat(counts.growing,'Growing')}${stat(counts.candidate,'Candidates')}${stat(counts.graduated,'Graduated')}</div>${legend}<div class="directory-tools seed-tools"><input id="seedFilter" type="search" placeholder="Filter Seeds…" aria-label="Filter Seeds"><select id="seedStatus"><option value="all">All statuses</option><option value="seed">Seeds</option><option value="growing">Growing</option><option value="candidate">Candidates</option><option value="graduated">Graduated</option></select><select id="seedProvenance"><option value="all">All provenance</option><option value="brandon">Brandon Original</option><option value="assisted">Brandon + AI Assisted</option><option value="prompted">AI from Brandon Prompt</option><option value="ai">AI-Generated</option><option value="uncertain">Provenance Uncertain</option></select><button class="btn secondary" id="randomSeed" type="button">Random Seed</button></div><div id="seedRows" class="work-list"></div><div class="callout"><strong>Provenance rule:</strong> Seed status never implies authorship. A Seed may be Brandon-original, AI-assisted, AI-generated from a Brandon concept, AI-generated, or uncertain; the archive records those separately.</div>`}

function mountSeeds(){const input=document.getElementById('seedFilter'),status=document.getElementById('seedStatus'),prov=document.getElementById('seedProvenance'),out=document.getElementById('seedRows'),random=document.getElementById('randomSeed');if(!out)return;const prm=hashParams();input.value=prm.get('q')||'';status.value=['all','seed','growing','candidate','graduated'].includes(prm.get('status'))?prm.get('status'):'all';prov.value=['all','brandon','assisted','prompted','ai','uncertain'].includes(prm.get('prov'))?prm.get('prov'):'all';function filtered(){const q=(input.value||'').toLowerCase(),st=status.value,pv=prov.value;return seedEntries().filter(x=>(st==='all'||x.status===st)&&(pv==='all'||x.provenance===pv)&&(!q||((x.title||'')+' '+(x.text||'')+' '+(x.notes||'')+' '+(x.source||'')).toLowerCase().includes(q)))}function state(){return qs('#seeds',{q:input.value,status:status.value==='all'?'':status.value,prov:prov.value==='all'?'':prov.value})}function draw(){const a=filtered();history.replaceState(null,'',state());out.innerHTML=a.length?a.map(seedRow).join(''):'<div class="empty">No Seeds match those filters.</div>';return a}function changed(){draw()}input.addEventListener('input',changed);status.addEventListener('change',changed);prov.addEventListener('change',changed);if(random)random.addEventListener('click',()=>{const a=draw();if(!a.length)return;const x=a[Math.floor(Math.random()*a.length)];const id='seed-'+String(x._key||x.id||x.workId||'item').replace(/[^a-z0-9_-]/gi,'-');const el=document.getElementById(id);if(el){el.classList.add('seed-focus');el.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>el.classList.remove('seed-focus'),1800)}});draw()}

function verificationCard(x,state){const d=candidateDecision(x,state);const lock=x.lockedEvidence?' locked':'';const btn=(kind,value,label)=>`<button type="button" class="verify-choice${d[kind+'Value']===value?' selected':''}" data-id="${esc(x.id)}" data-kind="${kind}" data-value="${value}"${x.lockedEvidence&&kind==='authorship'?' disabled':''}>${esc(label)}</button>`;return `<article class="verify-card${lock}" data-candidate="${esc(x.id)}"><div class="verify-card-head"><div><strong>${esc(x.source||'Unknown source')}</strong><div class="sub">${esc(x.location||'')}</div></div><div class="verify-values"><span>Authorship: <b>${d.authorshipValue>0?'+':''}${d.authorshipValue}</b></span><span>Confidence: <b>${d.confidenceValue}</b></span><span>Completion: <b>${d.completionValue}</b></span></div></div><pre class="poem-text verify-text">${esc(x.text||'')}</pre><p class="small"><strong>Evidence:</strong> ${esc(x.evidence||'No evidence note.')}</p><div class="verify-control"><strong>Who wrote it?</strong><div class="verify-buttons">${btn('authorship',1,'Mine · +1')}${btn('authorship',0,'Unsure · 0')}${btn('authorship',-1,'Not Mine · −1')}</div></div><div class="verify-control"><strong>What state is it in?</strong><div class="verify-buttons">${btn('completion',3,'Finished · 3')}${btn('completion',2,'Growing · 2')}${btn('completion',1,'Seed · 1')}${btn('completion',0,'Unsure · 0')}</div></div><div class="small verify-summary">Current: <strong>${esc(authorshipLabel(d.authorshipValue))}</strong> · ${esc(completionLabel(d.completionValue))} · ${esc(confidenceLabel(d.confidenceValue))}${d.verifiedAt?` · reviewed ${esc(fmtDate(d.verifiedAt))}`:''}${x.lockedEvidence?'<br><em>Authorship is evidence-locked unless stronger source evidence is found.</em>':''}</div></article>`}
function verification(){const xs=verificationCandidates();return `${pageTitle('Attribution control','Provenance Review','Mixed notebooks are reviewed passage by passage. Your direct confirmation outranks stylistic inference; uncertain material stays uncertain.')}<div class="callout"><strong>Values:</strong> Authorship +1 = Mine, 0 = Unsure, −1 = Not Mine. Confidence 3 = personally confirmed, 2 = strong independent evidence, 1 = probable, 0 = uncertain. Completion 3 = Finished, 2 = Growing, 1 = Seed, 0 = Unsure.</div><div class="directory-tools verify-toolbar"><select id="verifyFilter"><option value="all">All candidates</option><option value="unreviewed">Unreviewed</option><option value="strong-unresolved">Strong evidence · still unresolved</option><option value="mine">Mine</option><option value="external">Not Mine</option><option value="unsure">Unsure</option></select><button class="btn secondary" id="copyVerification" type="button">Copy Review JSON</button><button class="btn secondary" id="resetVerification" type="button">Reset Local Review</button></div><div id="verifyStats" class="stats"></div><div id="verifyRows"></div><div class="callout"><strong>To commit your review to the permanent archive:</strong> tap “Copy Review JSON” and paste it into ChatGPT. Browser choices are stored locally so the public site itself never gets write access to GitHub.</div>`}
function mountVerification(){const out=document.getElementById('verifyRows'),stats=document.getElementById('verifyStats'),filter=document.getElementById('verifyFilter'),copy=document.getElementById('copyVerification'),reset=document.getElementById('resetVerification');if(!out)return;function draw(){const state=readVerification(),xs=verificationCandidates();const resolved=xs.map(x=>({x,d:candidateDecision(x,state)}));const mine=resolved.filter(y=>y.d.authorshipValue===1).length,external=resolved.filter(y=>y.d.authorshipValue===-1).length,strong=resolved.filter(y=>y.d.authorshipValue===0&&y.d.confidenceValue>=2).length,reviewed=resolved.filter(y=>state[y.x.id]).length;stats.innerHTML=stat(xs.length,'candidates')+stat(reviewed,'reviewed locally')+stat(strong,'strong unresolved')+stat(mine,'Mine +1')+stat(external,'Not Mine −1');const mode=filter.value;const shown=resolved.filter(y=>mode==='all'||(mode==='unreviewed'&&!state[y.x.id])||(mode==='strong-unresolved'&&y.d.authorshipValue===0&&y.d.confidenceValue>=2)||(mode==='mine'&&y.d.authorshipValue===1)||(mode==='external'&&y.d.authorshipValue===-1)||(mode==='unsure'&&y.d.authorshipValue===0)).sort((a,b)=>{const ar=state[a.x.id]?1:0,br=state[b.x.id]?1:0;if(ar!==br)return ar-br;if(a.d.authorshipValue===0&&b.d.authorshipValue===0&&a.d.confidenceValue!==b.d.confidenceValue)return b.d.confidenceValue-a.d.confidenceValue;return String(a.x.source||'').localeCompare(String(b.x.source||''))});out.innerHTML=shown.length?shown.map(y=>verificationCard(y.x,state)).join(''):'<div class="empty">No candidates match this filter.</div>'}
out.addEventListener('click',e=>{const b=e.target.closest('.verify-choice');if(!b||b.disabled)return;const id=b.dataset.id,kind=b.dataset.kind,value=Number(b.dataset.value),state=readVerification(),x=verificationCandidates().find(v=>v.id===id);if(!x)return;const d=state[id]||{};if(kind==='authorship'){d.authorshipValue=value;d.confidenceValue=value===0?0:3}else if(kind==='completion'){d.completionValue=value}d.verifiedAt=new Date().toISOString();state[id]=d;writeVerification(state);draw()});
filter.addEventListener('change',draw);
copy.addEventListener('click',async()=>{const state=readVerification();const payload={schema:'idp-provenance-review-v1',archiveVersion:CM.archiveVersion,reviewedAt:new Date().toISOString(),decisions:verificationCandidates().filter(x=>state[x.id]).map(x=>({id:x.id,source:x.source,...candidateDecision(x,state)}))};const txt=JSON.stringify(payload,null,2);try{await navigator.clipboard.writeText(txt);copy.textContent='Copied';setTimeout(()=>copy.textContent='Copy Review JSON',1600)}catch(e){prompt('Copy this review JSON:',txt)}});
reset.addEventListener('click',()=>{if(confirm('Clear only the provenance-review choices stored in this browser?')){localStorage.removeItem(VERIFY_KEY);draw()}});
draw()}

function documents(){const docs=archiveDocuments();return `${pageTitle('Prose & source archive','Documents / Prose','Essays, reflections, experience reports, working files, and book-level source documents preserved alongside the poetry.')}${docs.length?`<div class="work-list">${docs.map(documentRow).join('')}</div>`:'<div class="empty">No prose/source documents have been indexed yet.</div>'}`}

function documentView(id){const x=archiveDocumentById(safeDec(id));if(!x)return missing('Document');const body=x.text?`<div class="panel"><pre class="poem-text document-text">${esc(x.text)}</pre></div>`:`<div class="panel"><p>${esc(x.description||'Source document indexed for provenance and version history.')}</p></div>`;const rel=Array.isArray(x.relatedTitles)&&x.relatedTitles.length?`<div class="callout"><strong>Related works:</strong> ${x.relatedTitles.map(esc).join(' • ')}</div>`:'';return `${crumb([['Documents / Prose','#documents'],[x.title||'Untitled document']])}${pageTitle(x.type||'Archive document',x.title||'Untitled document',x.source||'Recovered source material')}${metaBadges(x)}${body}${rel}${x.notes?`<div class="callout"><strong>Archive note:</strong> ${esc(x.notes)}</div>`:''}`}

function creative(id){const x=supplementalById(safeDec(id));if(!x)return missing('Creative work');return `${crumb([['Poetry','#poetry'],[x.title||'Untitled']])}${pageTitle('Reconciled creative record',x.title||'Untitled',x.source||'Later recovered material')}${metaBadges(x)}${provenanceMap(x)}<div class="poem-shell"><pre class="poem-text">${esc(x.text||'')}</pre><aside class="side-card"><dl><dt>Creative status</dt><dd>${esc(metaName('completion',x.status)||x.status||'unknown')}</dd><dt>Authorship / provenance</dt><dd>${esc(metaName('provenance',x.provenance)||x.provenance||'unknown')}</dd><dt>Provenance confidence</dt><dd>${esc(x.confidence&&CM.confidence&&CM.confidence[x.confidence]?CM.confidence[x.confidence]:'unknown')}</dd><dt>Source</dt><dd>${esc(x.source||'unknown')}</dd>${x.evidence?`<dt>Evidence</dt><dd>${esc(x.evidence)}</dd>`:''}</dl></aside></div>${x.notes?`<div class="callout"><strong>Archive note:</strong> ${esc(x.notes)}</div>`:''}`}

function fmtDate(s){if(!s)return 'unknown date';const d=new Date(String(s).replace(' UTC','Z'));return isNaN(d)?esc(s):d.toLocaleString(undefined,{year:'numeric',month:'short',day:'numeric',hour:s.length>10?'numeric':undefined,minute:s.length>10?'2-digit':undefined})}
function cleanBB(raw){let s=esc(raw||'');s=s.replace(/\[b(?::[^\]]+)?\]([\s\S]*?)\[\/b(?::[^\]]+)?\]/gi,'<strong>$1</strong>').replace(/\[i(?::[^\]]+)?\]([\s\S]*?)\[\/i(?::[^\]]+)?\]/gi,'<em>$1</em>').replace(/\[u(?::[^\]]+)?\]([\s\S]*?)\[\/u(?::[^\]]+)?\]/gi,'<u>$1</u>').replace(/\[quote(?::[^\]]+)?\]([\s\S]*?)\[\/quote(?::[^\]]+)?\]/gi,'<blockquote>$1</blockquote>').replace(/\[url(?:=[^\]]+)?\]/gi,'').replace(/\[\/url\]/gi,'').replace(/\[(?:img|\/img|size(?:=[^\]]+)?|\/size|color(?:=[^\]]+)?|\/color)(?::[^\]]+)?\]/gi,'').replace(/\r?\n/g,'<br>');return s}
function crumb(items){return `<div class="breadcrumbs">${items.map((x,i)=>i===items.length-1?esc(x[0]):`<a href="${x[1]}">${esc(x[0])}</a> -&gt; `).join('')}</div>`}
function stat(num,label){return `<div class="stat"><b>${n(num)}</b><span>${esc(label)}</span></div>`}
function excerpt(txt,q='',len=220){let s=String(txt||'').replace(/\[[^\]]+\]/g,' ').replace(/\s+/g,' ').trim();if(q){const i=s.toLowerCase().indexOf(q.toLowerCase());if(i>=0)s=s.slice(Math.max(0,i-70),Math.max(0,i-70)+len)}return esc(s.length>len?s.slice(0,len)+'…':s)}
function sectionHead(t,p=''){return `<div class="section-head"><h2>${esc(t)}</h2><p>${esc(p)}</p></div>`}
function pageTitle(k,t,p=''){return `${k?`<div class="eyebrow">${esc(k)}</div>`:''}<h1>${esc(t)}</h1>${p?`<p class="small">${esc(p)}</p>`:''}`}
function routeLink(h,label,cls=''){return `<a class="${cls}" href="${h}">${esc(label)}</a>`}

function home(){
 const s=C.meta.stats; const ev=C.evidence.slice(0,6);
 return `<section class="hero"><div class="hero-main"><div class="eyebrow">Recovered digital community • 2002-2005</div><h1>The message board came back.</h1><p>IDunnoPoetry survives in fragments: poems, usernames, diaries, arguments, jokes, friendships, and the words people left for one another more than twenty years ago.</p><p><a class="btn" href="#forums">Enter the forums</a> <a class="btn secondary" style="border-color:white;color:white" href="#poetry">Browse recovered poetry</a></p></div><aside class="hero-aside"><h2>A museum, not a resurrection</h2><p>This reconstruction preserves historically public material while deliberately leaving private messages, email addresses, IP addresses, passwords, and credentials out of the exhibit.</p><div class="source-note">Built from the union of two contradictory SQL backups. Missing records are treated as missing - never as evidence that something never existed.</div></aside></section>
 <div class="stats">${stat(s.users,'recoverable user IDs')}${stat(s.posts,'surviving public posts')}${stat(s.topics,'surviving topic IDs')}${stat(s.works,'recovered source-level works')}</div>
 ${sectionHead('Explore the archive','Eleven ways into the surviving IDP world')}
 <div class="grid"><a class="card" href="#forums"><h3>Message boards</h3><p>Browse recovered forums, topics, and public posts in their original conversational structure.</p></a><a class="card" href="#poetry"><h3>Poetry vault</h3><p>Hundreds of recovered creative records, including historical revisions and community submissions.</p></a><a class="card" href="#seeds"><h3>Seeds</h3><p>Incomplete pieces, fragments, active drafts, and works whose unfinished status is still under review.</p></a><a class="card" href="#documents"><h3>Documents / Prose</h3><p>Essays, manifestos, experience reports, source files, and book-level artifacts that belong beside the poetry without being mislabeled as poems.</p></a><a class="card" href="#verify"><h3>Verify authorship</h3><p>Review mixed-source notebook fragments and explicitly mark Mine, Not Mine, or Unsure.</p></a><a class="card" href="#media"><h3>Media archive</h3><p>Trace songs, poem-videos, spoken-word performances, and visual derivatives back to their canonical works.</p></a><a class="card" href="#people"><h3>People</h3><p>Find an old username and see the public traces that survive: posts, topics, and writing.</p></a><a class="card" href="#timeline"><h3>Timeline</h3><p>Watch recoverable registration and activity grow month by month across the surviving fragments.</p></a><a class="card" href="#search"><h3>Full-text search</h3><p>Search public post text, topic titles, usernames, and recovered poetry in one place.</p></a><a class="card" href="#exhibits"><h3>Guided exhibits</h3><p>Follow the strongest historical stories: growth, creative culture, support, loss, revision, and recovery.</p></a><a class="card" href="#voices"><h3>Reader impact</h3><p>See privacy-safe evidence of long-term readers, emotional support, classroom use, adaptations, and rediscovery.</p></a><a class="card" href="#reclaim"><h3>Reclaim your writing</h3><p>A former member can search an old handle and discover poetry they may have thought was gone.</p></a></div>
 ${sectionHead('Voices from the board','Contemporary statements preserved in public posts')}
 <div class="grid">${ev.map(e=>`<div class="card quote-card"><span class="pill gold">${esc(String(e.category).replaceAll('_',' '))}</span><q>${excerpt(e.excerpt,'',180)}</q><cite>${esc(e.username)} • ${esc(e.forum)} • ${fmtDate(e.date_utc)}</cite><p class="small"><a href="#topic/${topicForEvidence(e.post_id)}">Open context</a></p></div>`).join('')}</div>
 <div class="callout" style="margin-top:28px"><strong>Scale clue:</strong> only ${n(s.posts)} public post IDs survive, while later member counters total ${n(s.member_counter_sum)} posts and assigned post IDs reach ${n(s.max_post_id)}. The museum therefore shows fragments of a substantially larger historical board.</div>`
}
function topicForEvidence(pid){const p=P.find(x=>x.id===Number(pid));return p?p.t:''}

function firstPostForTopic(t){const direct=postById.get(Number(t?.first));if(direct)return direct;const ps=(postsByTopic.get(Number(t?.id))||[]).slice().sort((a,b)=>String(a.d).localeCompare(String(b.d)));return ps[0]||null}
function lastPostForTopic(t){const direct=postById.get(Number(t?.last));if(direct)return direct;const ps=(postsByTopic.get(Number(t?.id))||[]).slice().sort((a,b)=>String(a.d).localeCompare(String(b.d)));return ps[ps.length-1]||null}
function lastPostForForum(f){let best=null,bestTopic=null;for(const t of (topicsByForum.get(Number(f?.id))||[])){const p=lastPostForTopic(t);if(p&&(!best||String(p.d)>String(best.d))){best=p;bestTopic=t}}return best?{p:best,t:bestTopic}:null}
function userLinkForPost(p){if(!p)return '<span class="muted">unknown</span>';const u=userById.get(Number(p.u));const name=p.n||u?.n||'Anonymous';return u?`<a href="#user/${u.id}">${esc(name)}</a>`:esc(name)}
const threadStarterMap=window.IDP_THREAD_STARTERS||{};
function topicStarterUser(t){const uid=Number(threadStarterMap[String(t?.id)]||0);if(uid){const u=userById.get(uid);if(u)return u}const p=firstPostForTopic(t);if(!p)return null;return userById.get(Number(p.u))||{id:Number(p.u)||0,n:p.n||'Anonymous'}}
function topicStarterLink(t){const u=topicStarterUser(t);if(!u)return '<span class="muted">unknown</span>';return u.id&&userById.has(Number(u.id))?`<a href="#user/${u.id}">${esc(u.n)}</a>`:esc(u.n||'Anonymous')}
function topicStarterName(t){return topicStarterUser(t)?.n||'unknown'}
function topicLastPage(t){return Math.max(1,Math.ceil((postsByTopic.get(Number(t?.id))||[]).length/20))}
function latestReplyLink(t,label='Go to last surviving post'){const page=topicLastPage(t);return `<a class="mini-last-link" href="#topic/${t.id}/${page}" title="${esc(label)}"><img class="latest-reply-icon" src="assets/subsilver/icon_latest_reply.gif" alt="" aria-hidden="true"><span class="latest-reply-fallback">›</span></a>`}
function lastPostCell(t){const p=lastPostForTopic(t);if(!p)return '<span class="muted">not recovered</span>';return `${fmtDate(p.d)}<br>${userLinkForPost(p)} ${latestReplyLink(t)}`}

function forums(){
 const cats={};for(const f of C.forums){(cats[f.cat]??=[]).push(f)}
 let html=pageTitle('Forum Index','I Dunno Poetry','The surviving messageboard structure reconstructed from the public SQL snapshots.');
 html+=`<div class="forum-footerline"><b>${n(C.meta.stats.posts)}</b> surviving public posts • <b>${n(C.meta.stats.topics)}</b> surviving topics • <b>${n(C.meta.stats.users)}</b> recoverable member IDs</div>`;
 for(const [cat,fs] of Object.entries(cats)){
   html+=`<section class="forum-category"><div class="cat-title">${esc(cat)}<span class="cat-meta">${fs.length} surviving forum${fs.length===1?'':'s'}</span></div><div class="forum-table-head"><span></span><span>Forum</span><span>Topics</span><span>Posts</span><span>Last post</span></div>${fs.sort((a,b)=>b.sp-a.sp).map(f=>{const lp=lastPostForForum(f);return `<div class="forum-row"><div><span class="forum-icon" aria-hidden="true"></span></div><div class="forum-main"><a href="#forum/${f.id}">${esc(f.n)}</a><div class="desc">Recovered from ${esc(f.p)}</div></div><div class="count-cell">${n(f.st)}</div><div class="count-cell">${n(f.sp)}</div><div class="last-cell">${lp?`${fmtDate(lp.p.d)}<br>${userLinkForPost(lp.p)} ${latestReplyLink(lp.t,'Go to last surviving post in this forum')}`:'<span class="muted">not recovered</span>'}</div></div>`}).join('')}</section>`;
 }
 const newest=C.users.slice().sort((a,b)=>String(b.d).localeCompare(String(a.d)))[0];
 html+=`<div class="classic-index-footer"><section class="classic-stats"><div class="classic-box-title">Statistics</div><div class="classic-box-body">Surviving archive: <b>${n(C.meta.stats.posts)}</b> public posts in <b>${n(C.meta.stats.topics)}</b> topics.<br>Recoverable member IDs: <b>${n(C.meta.stats.users)}</b>.${newest?` Latest recoverable registration: <a href="#user/${newest.id}">${esc(newest.n)}</a> (${fmtDate(newest.d)}).`:''}</div></section><section class="classic-icon-key"><div class="classic-box-title">Historical subSilver icon key</div><div class="classic-box-body icon-key-row"><span><img src="assets/subsilver/folder_big.gif" alt=""> No new posts</span><span><img src="assets/subsilver/folder_new_big.gif" alt=""> New posts</span><span><img src="assets/subsilver/folder_locked_big.gif" alt=""> Forum locked</span></div><div class="classic-key-note">Visual reference only: the museum is read-only and does not recreate viewer-specific unread state.</div></section></div><div class="forum-footerline">Archive index • historical phpBB categories preserved where recoverable • counts reflect surviving records, not original totals</div>`;
 return html;
}
function forum(id,page=1){
 const f=forumById.get(Number(id));if(!f)return missing('Forum');
 const all=(topicsByForum.get(f.id)||[]).slice().sort((a,b)=>String(b.d).localeCompare(String(a.d)));
 page=Math.max(1,Number(page)||1);const per=20,pages=Math.max(1,Math.ceil(all.length/per));if(page>pages)page=pages;const ts=all.slice((page-1)*per,page*per);
 return `${crumb([['Forum Index','#forums'],[f.n]])}${pageTitle(f.cat,f.n,`${n(f.sp)} surviving posts • ${n(f.st)} surviving topics • page ${page} of ${pages}`)}${pager(`#forum/${f.id}/`,page,pages)}<div class="topic-table"><div class="topic-table-head"><span></span><span>Topics</span><span>Replies</span><span>Author</span><span>Views</span><span>Last post</span></div>${ts.length?ts.map(t=>{const fp=firstPostForTopic(t);return `<div class="topic-row"><div><span class="topic-icon" aria-hidden="true"></span></div><div class="topic-main"><a href="#topic/${t.id}">${esc(t.title)}</a><div class="desc"><strong>Started by ${topicStarterLink(t)}</strong> • topic #${n(t.id)} • ${esc(t.p)}</div></div><div class="count-cell">${n(t.r)}</div><div class="author-cell">${topicStarterLink(t)}</div><div class="count-cell">${n(t.v)}</div><div class="last-cell">${lastPostCell(t)}</div></div>`}).join(''):'<div class="empty">No surviving topics.</div>'}</div>${pager(`#forum/${f.id}/`,page,pages)}<div class="forum-footerline"><a href="#forums">Forum Index</a> -&gt; ${esc(f.n)} • 20 topics per page, matching the preserved IDP phpBB configuration • read-only museum reconstruction.</div>`
}
function topic(id,page=1){
 const t=topicById.get(Number(id));if(!t)return missing('Topic');const f=forumById.get(t.f);const all=(postsByTopic.get(t.id)||[]).slice().sort((a,b)=>String(a.d).localeCompare(String(b.d)));
 page=Math.max(1,Number(page)||1);const per=20,pages=Math.max(1,Math.ceil(all.length/per));if(page>pages)page=pages;const start=(page-1)*per,ps=all.slice(start,start+per);
 const siblings=(topicsByForum.get(t.f)||[]).slice().sort((a,b)=>String(a.d).localeCompare(String(b.d)));const si=siblings.findIndex(x=>x.id===t.id);const older=si>0?siblings[si-1]:null,newer=si>=0&&si<siblings.length-1?siblings[si+1]:null;
 return `${crumb([['Forum Index','#forums'],[f?f.n:'Forum',f?`#forum/${f.id}`:'#forums'],[t.title]])}${pageTitle('Recovered topic',t.title,`${all.length} surviving post${all.length===1?'':'s'} • started by ${displayText(topicStarterName(t))} • ${f?f.n:''} • page ${page} of ${pages}`)}${pager(`#topic/${t.id}/`,page,pages)}<div class="topic-prevnext"><span>${older?`<a href="#topic/${older.id}">View previous topic</a>`:'View previous topic'}</span><span>${newer?`<a href="#topic/${newer.id}">View next topic</a>`:'View next topic'}</span></div><div class="callout"><strong>Snapshot note:</strong> topic reply/view counters can exceed the posts visible here because the backups were already incomplete when preserved.</div><div class="post-columns-head"><span>Author</span><span>Message</span></div>${ps.map((p,i)=>postCard(p,start+i+1)).join('')}${pager(`#topic/${t.id}/`,page,pages)}${crumb([['Forum Index','#forums'],[f?f.n:'Forum',f?`#forum/${f.id}`:'#forums'],[t.title]])}`
}
function postCard(p,num){
 const u=userById.get(p.u);const uname=p.n||u?.n||'Anonymous';
 return `<article class="post" id="post-${p.id}"><div class="post-topline"><span><img class="mini-post-icon" src="assets/subsilver/icon_minipost.gif" alt="" aria-hidden="true"><b>Posted:</b> ${fmtDate(p.d)}</span><span><b>Post #${num}</b> • id ${n(p.id)} • ${esc(p.p)}</span></div><aside class="post-author"><div class="username"><a href="#user/${p.u}">${esc(uname)}</a></div>${u?`<dl><dt>Joined:</dt><dd>${fmtDate(u.d)}</dd><dt>Historical posts:</dt><dd>${n(u.pc)}</dd><dt>Surviving posts:</dt><dd>${n(u.sp)}</dd><dt>User ID:</dt><dd>${n(u.id)}</dd></dl>`:`<div class="small">Historical account record not recovered.</div>`}</aside><div class="post-message">${p.s?`<div class="kicker">Post subject: ${esc(p.s)}</div>`:''}${cleanBB(p.x)}</div></article>`
}
function people(){return `${pageTitle('Directory','People','Historical public usernames only; no email addresses or private profile data are displayed.')}<div class="directory-tools"><input id="peopleFilter" type="search" placeholder="Filter usernames…" aria-label="Filter usernames"><select id="peopleSort"><option value="posts">Most historical posts</option><option value="survive">Most surviving posts</option><option value="name">Username A-Z</option><option value="date">Earliest registration</option></select></div><div id="peopleRows" class="people-list"></div>`}
function mountPeople(){const input=document.getElementById('peopleFilter'), sort=document.getElementById('peopleSort'), out=document.getElementById('peopleRows');if(!out)return;function draw(){let q=(input.value||'').toLowerCase();let a=C.users.filter(u=>!q||u.n.toLowerCase().includes(q));const mode=sort.value;a.sort((x,y)=>mode==='name'?x.n.localeCompare(y.n):mode==='date'?String(x.d).localeCompare(String(y.d)):mode==='survive'?y.sp-x.sp:y.pc-x.pc);out.innerHTML=a.slice(0,500).map(u=>`<div class="row"><div><a href="#user/${u.id}">${esc(u.n)}</a><div class="sub">Registered ${fmtDate(u.d)} • user ID ${u.id}</div></div><div class="counts">${n(u.pc)} profile counter<br>${n(u.sp)} surviving posts</div></div>`).join('')+(a.length>500?`<div class="empty">Showing 500 of ${n(a.length)} matches. Narrow the filter to see more.</div>`:'')}
input.addEventListener('input',draw);sort.addEventListener('change',draw);draw()}
function user(id,page=1){const u=userById.get(Number(id));if(!u)return missing('User');const ups=(postsByUser.get(u.id)||[]).slice().sort((a,b)=>String(b.d).localeCompare(String(a.d)));const ws=worksByUser.get((u.n||'').toLowerCase())||[];page=Math.max(1,Number(page)||1);const per=100,pages=Math.max(1,Math.ceil(ups.length/per)),slice=ups.slice((page-1)*per,page*per);return `${crumb([['People','#people'],[u.n]])}${pageTitle('Historical public profile',u.n,`User ID ${u.id} • registered ${fmtDate(u.d)}`)}<div class="stats">${stat(u.pc,'historical profile post counter')}${stat(u.sp,'surviving public posts')}${stat(ws.length,'recovered creative works')}${stat(ups.length,'public posts in museum union')}</div>${ws.length?sectionHead('Recovered writing',`${ws.length} selected source records`)+`<div class="work-list">${ws.slice().sort((a,b)=>String(b.d).localeCompare(String(a.d))).map(workRow).join('')}</div>`:''}${sectionHead('Surviving public posts',`Newest first • page ${page} of ${pages}`)}${slice.map(p=>{const t=topicById.get(p.t);return `<article class="post"><header class="post-head"><span>${fmtDate(p.d)} • ${t?`<a href="#topic/${t.id}">${esc(t.title)}</a>`:'topic unavailable'}</span><span>post ${n(p.id)}</span></header><div class="post-body">${excerpt(p.x,'',650)}</div></article>`}).join('')||'<div class="empty">No surviving public posts.</div>'}${pager(`#user/${u.id}/`,page,pages)}`}
function pager(prefix,page,pages){if(pages<=1)return '';let out='<nav class="pagination" aria-label="Pagination">';for(let i=1;i<=pages;i++){if(i===1||i===pages||Math.abs(i-page)<=2)out+=`<a class="${i===page?'current':''}" href="${prefix}${i}">${i}</a>`;else if(i===page-3||i===page+3)out+='<span>…</span>'}return out+'</nav>'}

function poetry(){const key=`<div class="callout provenance-key"><strong>Authorship labels:</strong> Brandon Original = directly attributable to Brandon; Brandon + AI Assisted = Brandon-authored with AI help; AI-Generated from Brandon Prompt/Concept = substantially generated by AI from Brandon input; AI-Generated = primarily AI-written; Provenance Uncertain = evidence is insufficient to assign authorship safely.</div>`;return `${pageTitle('Creative archive','Poetry','Historical source records plus later reconciled creative material. Reposts, revisions, Seeds, and AI involvement are preserved rather than silently flattened together.')}${key}<div class="directory-tools"><input id="poetryFilter" type="search" placeholder="Filter title, username, or credit…" aria-label="Filter poetry"><select id="poetrySource"><option value="all">All sources</option><option value="main_site_brandon">Brandon main archive</option><option value="main_site_community">Community submissions</option><option value="forum_poetry_thread">Forum poetry</option><option value="supplemental_reconciled">Reconciled later / AI-involved</option></select></div><div id="poetryRows" class="work-list"></div>`}
function workRow(w){const mm=mediaForTitle(w.title),m=workMeta(w);return `<div class="row"><div><a href="#poem/${w.id}">${esc(w.title)}</a><div class="sub">${esc(w.u||w.credit||'Unknown')} • ${fmtDate(w.d)} • ${esc(w.forum||w.type)}${mm.length?` • ${mm.length} media asset${mm.length===1?'':'s'}`:''}</div>${metaBadges(m)}</div><div class="counts">${w.vc>1?`${w.vc} versions<br>`:''}${esc(w.conf||'')}</div></div>`}
function mountPoetry(){const input=document.getElementById('poetryFilter'),src=document.getElementById('poetrySource'),out=document.getElementById('poetryRows');if(!out)return;const prm=hashParams();const srcs=['all','main_site_brandon','main_site_community','forum_poetry_thread','supplemental_reconciled'];input.value=prm.get('q')||'';src.value=srcs.includes(prm.get('src'))?prm.get('src'):'all';
function state(p){return qs('#poetry',{q:input.value,src:src.value==='all'?'':src.value,p:p>1?p:''})}
function draw(rawPage){const q=(input.value||'').toLowerCase(),s=src.value;let a=s==='supplemental_reconciled'?[]:Q.works.filter(w=>(s==='all'||w.type===s)&&(!q||(w.title+' '+w.u+' '+w.credit).toLowerCase().includes(q)));let extras=(s==='all'||s==='supplemental_reconciled')?supplementalWorks().filter(x=>!q||((x.title||'')+' '+(x.text||'')+' '+(x.source||'')+' '+(x.notes||'')).toLowerCase().includes(q)):[];const pg=paginate(a,100,rawPage);if(String(rawPage??'1')!==String(pg.page))history.replaceState(null,'',state(pg.page));let html=pg.items.map(workRow).join('');if(extras.length)html+=(html?sectionHead('Reconciled later / AI-involved',`${extras.length} separately sourced creative record${extras.length===1?'':'s'}`):'')+extras.map(supplementalRow).join('');out.innerHTML=(html||'<div class="empty">No matching recovered works.</div>')+(a.length?`<div class="pager-row">${pagerNav(state,pg,'recovered works')}</div>`:'')}
function changed(){history.replaceState(null,'',state(1));draw(1)}
input.addEventListener('input',changed);src.addEventListener('change',changed);draw(prm.get('p')||1)}
function mediaKey(v){return String(v||'').normalize('NFKD').toLowerCase().replace(/[’‘'\"“”]/g,'').replace(/[^a-z0-9]+/g,'')}
function mediaForTitle(title){const k=mediaKey(title);return [...(M.assets||[]),...(Y.relevantVideos||[])].filter(a=>mediaKey(a.canonicalTitle||a.work)===k)}
function poemForMediaWork(title){const k=mediaKey(title);return Q.works.find(w=>mediaKey(w.title)===k)||null}
function mediaCounts(items){const c={Audio:0,Video:0,Image:0};for(const a of items)c[a.type]=(c[a.type]||0)+1;return c}
function mediaUrl(a){if(!a)return '';if(a.publicUrl)return a.publicUrl;if(a.publicPath)return a.publicPath;const base=String(CFG.mediaBaseUrl||'').replace(/\/+$/,'');return base&&a.objectKey?base+'/'+a.objectKey:''}
function renderPublishedMedia(a){const url=mediaUrl(a);if(!url)return '';const src=esc(url),title=esc(a.title||a.work||'Published media');if(a.youtubeId)return `<div class="media-preview youtube-preview"><strong>${title}</strong><div class="video-frame"><iframe loading="lazy" src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(a.youtubeId)}" title="${title}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe></div><div class="small">${esc(a.duration||'')} ${a.views!=null?' • '+n(a.views)+' views':''} • <a href="${src}" target="_blank" rel="noopener noreferrer">Open on YouTube</a></div>${a.mappingEvidence?`<div class="source-note">Linked by upload title. Audio and lyric comparison pending.</div>`:''}</div>`;if(a.type==='Image')return `<figure class="media-preview"><img src="${src}" alt="${title}" loading="lazy"><figcaption>${title}</figcaption></figure>`;if(a.type==='Audio')return `<div class="media-preview"><strong>${title}</strong><audio controls preload="metadata" src="${src}"></audio></div>`;if(a.type==='Video')return `<div class="media-preview"><strong>${title}</strong><video controls preload="metadata" src="${src}"></video></div>`;return ''}

function poem(id){const w=Q.works[Number(id)];if(!w)return missing('Poem');const m=workMeta(w),media=mediaForTitle(w.title),mc=mediaCounts(media);const vs=Q.versions[String(w.id)]||[];const topic=w.topic?topicById.get(Number(w.topic)):null;const comments=topic?(postsByTopic.get(topic.id)||[]).filter(p=>String(p.id)!==String(w.post)):[];return `${crumb([['Poetry','#poetry'],[w.title]])}${pageTitle(w.type.replaceAll('_',' '),w.title,`${esc(w.u||w.credit||'Unknown')} • ${fmtDate(w.d)}`)}${metaBadges(m)}${provenanceMap(m)}<div class="poem-shell"><pre class="poem-text">${esc(w.x)}</pre><aside class="side-card"><dl><dt>Username</dt><dd>${w.u?userLinkByName(w.u):'unknown'}</dd>${w.credit&&w.credit!==w.u?`<dt>Published credit</dt><dd>${esc(w.credit)}</dd>`:''}<dt>Source</dt><dd>${esc(w.forum||w.type)}</dd><dt>Confidence</dt><dd>${esc(w.conf||'')}</dd>${m.status?`<dt>Creative status</dt><dd>${esc(metaName('completion',m.status)||m.status)}</dd>`:''}${m.provenance?`<dt>Authorship / provenance</dt><dd>${esc(metaName('provenance',m.provenance)||m.provenance)}</dd>`:''}${m.confidence&&CM.confidence&&CM.confidence[m.confidence]?`<dt>Provenance confidence</dt><dd>${esc(CM.confidence[m.confidence])}</dd>`:''}<dt>Versions preserved</dt><dd>${n(w.vc)}</dd>${topic?`<dt>Original topic</dt><dd><a href="#topic/${topic.id}">${esc(topic.title)}</a></dd>`:''}</dl></aside></div>${media.length?sectionHead('Preserved media',`${media.length} cataloged derivative${media.length===1?'':'s'} linked to this work`)+`<div class="panel"><div><span class="pill">${mc.Audio||0} audio</span><span class="pill">${mc.Video||0} video</span><span class="pill">${mc.Image||0} image</span></div><p class="small">These assets are cataloged and linked to this work, but private Drive identifiers are deliberately not exposed. Public playback appears only for files intentionally published into the museum.</p>${media.some(a=>mediaUrl(a))?`<div class="published-media">${media.filter(a=>mediaUrl(a)).map(renderPublishedMedia).join('')}</div>`:''}<details><summary>Show cataloged media</summary><div class="work-list" style="margin-top:6px">${media.map(a=>`<div class="row"><div><strong>${esc(a.title)}</strong><div class="sub">${esc(a.collection)} • ${esc(a.type)} • ${esc(a.format)}</div></div><div class="counts">${Number(a.sizeMB||0).toLocaleString()} MB${a.duplicate?' • duplicate candidate':''}</div></div>`).join('')}</div></details></div>`:''}${vs.length>1?sectionHead('Preserved versions',`${vs.length} database snapshots/versions`)+`<div class="grid">${vs.map(v=>`<div class="card"><h3>${esc(v.snapshot)}</h3><p>${esc(v.title)} • ${fmtDate(v.d)}</p><details><summary>Read this version</summary><pre class="poem-text" style="font-size:14px;margin-top:10px">${esc(v.x)}</pre></details></div>`).join('')}</div>`:''}${comments.length?sectionHead('Original reactions',`${comments.length} surviving replies in the topic`)+comments.map((p,i)=>postCard(p,i+1)).join(''):''}`}
function userIdForName(name){const u=C.users.find(x=>x.n.toLowerCase()===String(name).toLowerCase());return u?u.id:null}
function userLinkByName(name){const id=userIdForName(name);return id===null?esc(name):`<a href="#user/${id}">${esc(name)}</a>`}

function timeline(){const rows=C.timeline.filter(x=>String(x.month)<='2005-02');const maxR=Math.max(...rows.map(x=>Number(x.registrations)||0)),maxP=Math.max(...rows.map(x=>Number(x.surviving_public_posts_union)||0));return `${pageTitle('Chronology','Timeline','Month-by-month evidence from recoverable registrations and public records. Surviving post counts are incomplete fragments, not traffic analytics.')}<div class="callout"><strong>Archive range:</strong> recoverable registrations begin Oct. 19, 2002; surviving forum activity reaches Feb. 13, 2005; the main poetry table continued through Apr. 4, 2011.</div><div class="timeline" style="margin-top:24px">${rows.map(r=>`<div class="time-item"><strong>${esc(r.month)}</strong><div class="small">${n(r.registrations)} registrations • ${n(r.cumulative_registered_users_recoverable)} cumulative recoverable IDs • ${n(r.surviving_topics_union)} surviving topics</div><div class="bars"><div class="barline"><span>registrations</span><div class="bar"><i style="width:${(Number(r.registrations)||0)/maxR*100}%"></i></div><b>${n(r.registrations)}</b></div><div class="barline"><span>surviving posts</span><div class="bar"><i style="width:${(Number(r.surviving_public_posts_union)||0)/maxP*100}%"></i></div><b>${n(r.surviving_public_posts_union)}</b></div></div></div>`).join('')}</div>`}

function search(q=''){q=safeDec(q);const prm=hashParams();let html=pageTitle('Archive-wide','Search','Search public posts, topic titles, usernames, recovered poetry, Seeds, and prose/source documents.');html+=`<form class="searchbox" id="searchForm"><input id="searchInput" value="${esc(q)}" type="search" placeholder="Try a username, phrase, poem title, seed, document…"><button class="btn">Search</button></form>`;if(!q)return html+'<div class="empty">Enter at least two characters.</div>';if(q.length<2)return html+'<div class="empty">Please use at least two characters.</div>';const low=q.toLowerCase();const us=C.users.filter(u=>u.n.toLowerCase().includes(low)),ts0=C.topics.filter(t=>t.title.toLowerCase().includes(low)),ws0=Q.works.filter(w=>(w.title+' '+w.u+' '+w.credit+' '+w.x).toLowerCase().includes(low)),xs0=supplementalWorks().filter(x=>((x.title||'')+' '+(x.text||'')+' '+(x.notes||'')+' '+(x.source||'')).toLowerCase().includes(low)),ss0=seedEntries().filter(x=>((x.title||'')+' '+(x.text||'')+' '+(x.notes||'')+' '+(x.source||'')).toLowerCase().includes(low)),ds0=archiveDocuments().filter(x=>((x.title||'')+' '+(x.type||'')+' '+(x.text||'')+' '+(x.description||'')+' '+(x.notes||'')+' '+(x.source||'')+' '+((x.tags||[]).join(' '))).toLowerCase().includes(low)),ps0=P.filter(p=>(p.n+' '+p.s+' '+p.x).toLowerCase().includes(low));const gU=paginate(us,30,prm.get('pu')),gT=paginate(ts0,40,prm.get('pt')),gW=paginate(ws0,60,prm.get('pw')),gX=paginate(xs0,60,prm.get('px')),gS=paginate(ss0,60,prm.get('ps')),gD=paginate(ds0,60,prm.get('pd')),gP=paginate(ps0,120,prm.get('pp'));const cur={pu:gU.page,pt:gT.page,pw:gW.page,px:gX.page,ps:gS.page,pd:gD.page,pp:gP.page};const sh=(k,sec)=>i=>{const o={...cur,[k]:i,sec};for(const x of['pu','pt','pw','px','ps','pd','pp'])if(o[x]===1)o[x]='';return qs('#search/'+encodeURIComponent(q),o)};html+=`<div class="stats">${stat(gU.total,'username matches')}${stat(gT.total,'topic-title matches')}${stat(gW.total,'poetry matches')}${stat(gX.total,'reconciled creative matches')}${stat(gS.total,'seed matches')}${stat(gD.total,'document matches')}${stat(gP.total,'public-post matches')}</div>`;if(gU.total)html+=`<div id="sec-people"></div>`+sectionHead('People')+`<div class="people-list">${gU.items.map(u=>`<div class="row"><div><a href="#user/${u.id}">${esc(u.n)}</a></div><div class="counts">${n(u.pc)} profile counter</div></div>`).join('')}</div>`+pagerNav(sh('pu','people'),gU,'username matches');if(gT.total)html+=`<div id="sec-topics"></div>`+sectionHead('Topics')+`<div class="topic-list">${gT.items.map(t=>`<div class="row"><div><a href="#topic/${t.id}">${esc(t.title)}</a><div class="sub">${esc(forumById.get(t.f)?.n||'')}</div></div><div class="counts">${n(t.r)} replies</div></div>`).join('')}</div>`+pagerNav(sh('pt','topics'),gT,'topic-title matches');if(gW.total)html+=`<div id="sec-poetry"></div>`+sectionHead('Poetry')+`<div class="work-list">${gW.items.map(workRow).join('')}</div>`+pagerNav(sh('pw','poetry'),gW,'poetry matches');if(gX.total)html+=`<div id="sec-reconciled"></div>`+sectionHead('Reconciled later / AI-involved')+`<div class="work-list">${gX.items.map(supplementalRow).join('')}</div>`+pagerNav(sh('px','reconciled'),gX,'reconciled creative matches');if(gS.total)html+=`<div id="sec-seeds"></div>`+sectionHead('Seeds')+`<div class="work-list">${gS.items.map(x=>`<div class="row seed-row"><div>${x.workId!=null?`<a href="#poem/${x.workId}">${esc(x.title||'Untitled seed')}</a>`:`<a href="#seeds">${esc(x.title||'Untitled seed')}</a>`}<div class="sub">${esc(x.source||'source under review')}${x.date?` • ${fmtDate(x.date)}`:''}</div>${metaBadges(x)}<div class="small">${excerpt(x.text||x.notes||'',q,240)}</div></div></div>`).join('')}</div>`+pagerNav(sh('ps','seeds'),gS,'seed matches');if(gD.total)html+=`<div id="sec-documents"></div>`+sectionHead('Documents / Prose')+`<div class="work-list">${gD.items.map(documentRow).join('')}</div>`+pagerNav(sh('pd','documents'),gD,'document matches');if(gP.total)html+=`<div id="sec-posts"></div>`+sectionHead('Public posts',`${n(gP.total)} matches`)+gP.items.map(p=>{const t=topicById.get(p.t);return `<article class="post"><header class="post-head"><span><a href="#user/${p.u}">${esc(p.n)}</a> • ${fmtDate(p.d)}</span><span>${t?`<a href="#topic/${t.id}">${esc(t.title)}</a>`:''}</span></header><div class="post-body">${excerpt(p.x,q,360)}</div></article>`}).join('')+pagerNav(sh('pp','posts'),gP,'public-post matches');if(!gU.total&&!gT.total&&!gW.total&&!gX.total&&!gS.total&&!gD.total&&!gP.total)html+='<div class="empty">No matches found.</div>';return html}
function mountSearch(q){const form=document.getElementById('searchForm');if(form)form.addEventListener('submit',e=>{e.preventDefault();const v=document.getElementById('searchInput').value.trim();location.hash='#search/'+encodeURIComponent(v)})}

function reclaim(q=''){q=decodeURIComponent(q||'');let matched=[];if(q){const low=q.toLowerCase();matched=Q.works.filter(w=>(w.u+' '+w.credit).toLowerCase().includes(low));}
 return `${pageTitle('Lost-and-found writing','Reclaim your poems','If you remember an IDP username or published credit, search it here. The museum exposes no historical email address; identity verification can happen privately with the archive owner.')}<div class="callout"><strong>Why this exists:</strong> many contributors probably do not possess their early-2000s writing anymore. The recovery bundles were designed so one person’s work can be returned without handing over the raw database or anybody else’s private data.</div><form class="searchbox" id="reclaimForm"><input id="reclaimInput" value="${esc(q)}" type="search" placeholder="Old username or author credit"><button class="btn">Find writing</button></form>${q?(matched.length?`<div class="work-list">${matched.slice(0,300).map(workRow).join('')}</div>`:'<div class="empty">No recovered creative records match that name. Try a partial username.</div>'):`<div class="panel"><h2>How reclamation works</h2><ol><li>Search an old username, handle, or published author credit.</li><li>Open the recovered works and confirm that the material is yours.</li><li>Contact the archive owner through <a href="${esc(CFG.contactUrl||'#')}" target="_blank" rel="noopener">${esc(CFG.siteLabel||'the archive site')}</a>. Historical contact data can be used privately for corroboration where appropriate, but is never published.</li><li>The person can receive their own recovered bundle, including older versions when preserved.</li></ol></div>`}`}
function mountReclaim(){const f=document.getElementById('reclaimForm');if(f)f.addEventListener('submit',e=>{e.preventDefault();location.hash='#reclaim/'+encodeURIComponent(document.getElementById('reclaimInput').value.trim())})}

function mediaArchive(){
 const privateAssets=M.assets||[],yt=Y.relevantVideos||[],assets=[...privateAssets,...yt],st=M.stats||{},published=assets.filter(a=>mediaUrl(a));const by=new Map();for(const a of assets){const key=a.canonicalTitle||a.work;if(!by.has(key))by.set(key,[]);by.get(key).push(a)}const groups=[...by.entries()].sort((a,b)=>b[1].length-a[1].length||a[0].localeCompare(b[0]));
 return `${pageTitle('Multimedia lineage','Media Archive','Songs, poem-videos, spoken-word performances, public YouTube uploads, and visual derivatives linked back to their canonical written works.')}
 <div class="callout"><strong>Two preservation layers:</strong> the private master archive indexes ${n(st.assets||privateAssets.length)} source media assets totaling about ${Number(st.totalMB||0).toLocaleString()} MB. The public eXemptus / @idunnopoetry channel currently contributes ${n(yt.length)} clearly archive-relevant YouTube uploads. Private Google Drive IDs remain excluded.</div>
 <div class="stats">${stat(groups.length,'works / archive groups with media')}${stat(st.video||0,'private videos')}${stat(st.audio||0,'private audio files')}${stat(yt.length,'public YouTube uploads')}</div>
 <div class="panel"><strong>YouTube source:</strong> <a href="${esc(Y.channel?.url||'https://www.youtube.com/@idunnopoetry')}" target="_blank" rel="noopener noreferrer">${esc(Y.channel?.title||'eXemptus')} ${esc(Y.channel?.handle||'@idunnopoetry')}</a> <span class="pill">${n(Y.channel?.subscribers||0)} subscribers</span> <span class="pill">${n(Y.channel?.reportedVideoCount||0)} channel count recorded${Y.channel?.reportedVideoCountChecked?' '+esc(Y.channel.reportedVideoCountChecked):''}</span> <span class="pill warn">${n(Y.channel?.unresolvedCount||0)} channel-count items not yet enumerated</span><p class="small"><strong>Last successful scan:</strong> ${esc(Y.sync?.lastRun||Y.checked||'not recorded')} · ${n(Y.sync?.enumerated||0)} unique uploads enumerated${Y.sync?.enumeratedByTab?' ('+Object.entries(Y.sync.enumeratedByTab).map(([tab,count])=>esc(tab)+': '+n(count)).join(', ')+')':''}.${Y.sync?.notSeen?' '+n(Y.sync.notSeen)+' preserved records were not seen in the latest scan.':''}</p><strong>Private source collections:</strong> ${(M.collections||[]).map(x=>`<span class="pill">${esc(x)}</span>`).join(' ')} <span class="pill warn">${n(st.duplicateCandidates||0)} duplicate candidates</span></div>
 <div class="panel"><strong>Publicly playable now:</strong> ${n(published.length)} catalog entries. YouTube videos play through privacy-enhanced embeds; private originals stay catalog-only until deliberately published or migrated to object storage.</div>
 ${(Y.reviewQueue||[]).length?`<div class="panel"><strong>YouTube review queue:</strong> ${n((Y.reviewQueue||[]).length)} public channel uploads remain unlinked. The notes below explain what is known from their titles and what still needs review.<details><summary>Show uploads and review notes</summary><div class="work-list">${(Y.reviewQueue||[]).map(v=>`<div class="row"><div><a href="${esc(v.publicUrl||'#')}" target="_blank" rel="noopener noreferrer">${esc(v.title||v.youtubeId)}</a>${v.reviewCategory?`<div class="sub">${esc(v.reviewCategory)}</div>`:''}<p class="small">${esc(v.reason||'Work association needs review.')}</p>${v.reviewedAt?`<div class="small">Title reviewed ${esc(v.reviewedAt)}</div>`:''}</div><div class="counts">${v.views!=null?n(v.views)+' views':''}${v.duration?'<br>'+esc(v.duration):''}${v.syncStatus?'<br>Not seen in latest scan':''}</div></div>`).join('')}</div></details></div>`:''}
 ${sectionHead('Media by work',`${groups.length} reconciled work / archive labels represented`)}
 <div class="grid">${groups.map(([work,items])=>{const c=mediaCounts(items),pw=poemForMediaWork(work);const ytCount=items.filter(a=>a.youtubeId).length;return `<article class="card"><h3>${pw?`<a href="#poem/${pw.id}">${esc(work)}</a>`:esc(work)}</h3><div><span class="pill">${c.Video||0} video</span><span class="pill">${c.Audio||0} audio</span><span class="pill">${c.Image||0} image</span>${ytCount?`<span class="pill gold">${ytCount} YouTube</span>`:''}</div><p class="small">${items.slice(0,4).map(a=>esc(a.title)).join(' • ')}${items.length>4?' • …':''}</p>${items.some(a=>a.youtubeId)?`<div class="published-media">${items.filter(a=>a.youtubeId).slice(0,2).map(renderPublishedMedia).join('')}</div>`:''}<details><summary>Show all ${items.length}</summary><div class="source-note">${items.map(a=>`${esc(a.title)} — ${esc(a.collection)} (${esc(a.format)}${a.sizeMB?', '+Number(a.sizeMB||0).toLocaleString()+' MB':''}${a.duration?', '+esc(a.duration):''})${mediaUrl(a)?' [public]':''}${a.duplicate?' [duplicate candidate]':''}`).join('<br>')}</div></details></article>`}).join('')}</div>
 <div class="source-note">${esc(M.privacy||'Private storage identifiers are excluded from the public catalog.')} ${esc(Y.methodology||'')}</div>`;
}

function readerImpact(){
 const entries=(R.entries||[]).slice().sort((a,b)=>String(a.date).localeCompare(String(b.date)));
 const longTerm=entries.filter(e=>e.category==='long_term_reader').length;
 const applied=entries.filter(e=>e.category==='education'||e.category==='adaptation').length;
 const privateCount=entries.filter(e=>!e.public).length;
 const label=x=>String(x||'reader evidence').replaceAll('_',' ');
 return `${pageTitle('Independent contemporary evidence','Reader Impact','Privacy-safe summaries of surviving correspondence and public interaction records showing how people used, remembered, and responded to IDunnoPoetry.')}
 <div class="callout"><strong>Evidence standard:</strong> these records document individual experiences; they do <em>not</em> establish a total audience size. Private correspondence is anonymized and paraphrased. Raw emails, addresses, IPs, and message identifiers are not published here.</div>
 <div class="stats">${stat(entries.length,'documented impact records')}${stat('2005','earliest surviving correspondence')}${stat(longTerm,'long-term readership records')}${stat(applied,'education / adaptation records')}</div>
 <div class="panel"><h2>What the correspondence adds</h2><p>The forum database can show posts, users, and poems. Correspondence shows what happened beyond those tables: readers returning after years, people using poems in school and teaching, song and social-media adaptations, and readers describing the writing as a source of identification or support.</p><p>Two especially strong chronology clues are independent: a March 2006 correspondent said they had followed the poetry for about four years, implying readership around 2002; a March 2015 correspondent said they first discovered IDunnoPoetry in 2003 and rediscovered it nearly twelve years later.</p></div>
 ${sectionHead('Surviving reader evidence',`${entries.length} privacy-safe records • ${privateCount} derived from private correspondence`)}
 <div class="grid">${entries.map(e=>`<article class="card impact-card"><div><span class="pill gold">${esc(e.date.slice(0,4))}</span><span class="pill">${esc(label(e.category))}</span></div><h3>${esc(e.related_work||'IDunnoPoetry')}</h3><p>${esc(e.summary)}</p><div class="source-note"><strong>Source class:</strong> ${esc(e.channel)} • ${e.public?'public interaction':'private correspondence, paraphrased'}</div></article>`).join('')}</div>
 <div class="source-note"><strong>Methodology:</strong> ${esc(R.methodology||'Private correspondence is summarized without publishing identifying information or raw message text.')}</div>`
}
function exhibits(){
 const s=C.meta.stats;const positive=C.evidence.filter(e=>String(e.category).toLowerCase()!=='counterevidence').slice(0,5);const counter=C.evidence.find(e=>String(e.category).toLowerCase()==='counterevidence');
 return `${pageTitle('Guided history','Museum Exhibits','Curated paths through the recovered record. Verified database evidence, archival inference, and creator recollection remain explicitly separate.')}
 <section class="forum-category"><div class="cat-title">01 · Before the Feed</div><div class="panel"><h2>A social network organized around writing</h2><p>IDunnoPoetry’s recoverable registrations begin in October 2002. The preserved board contains ${n(s.users)} user IDs, ${n(s.topics)} topic IDs, and 60 forum structures spanning poetry, diaries, advice, debate, music, images, games, and ordinary conversation.</p><p><a href="#forums">Walk the reconstructed forum index →</a></p></div></section>
 <section class="forum-category"><div class="cat-title">02 · Words Became Social Infrastructure</div><div class="panel"><h2>Poems did not sit alone</h2><p>The recovery identified ${n(s.works)} source-level creative records and ${n(s.poetry_comments)} surviving replies to poetry threads. The writing survives together with fragments of its original audience: encouragement, interpretation, jokes, arguments, and friendship.</p><p><a href="#poetry">Browse the poetry vault →</a></p></div></section>
 <section class="forum-category"><div class="cat-title">03 · Support, Belonging — and the Counterevidence</div><div class="grid">${positive.map(e=>`<div class="card quote-card"><q>${excerpt(e.excerpt,'',190)}</q><cite>${esc(e.username)} • ${fmtDate(e.date_utc)}</cite></div>`).join('')}${counter?`<div class="card danger-callout"><h3>Necessary counterpoint</h3><p>${excerpt(counter.excerpt,'',230)}</p><div class="meta">${esc(counter.username)} • ${fmtDate(counter.date_utc)}</div></div>`:''}</div></section>
 <section class="forum-category"><div class="cat-title">04 · Revision Archaeology</div><div class="panel"><h2>The poems themselves changed</h2><p>The early backup contains 143 Brandon poem IDs. Of those, 97 differ in title or text in the later snapshot. The database therefore preserves a genuine writing-development record rather than merely duplicate copies.</p><p><a href="#poetry">Explore recovered works and versions →</a></p></div></section>
 <section class="forum-category"><div class="cat-title">05 · The Missing Majority</div><div class="panel"><h2>${n(s.posts)} surviving posts are only the wreckage</h2><p>Later member profile counters total ${n(s.member_counter_sum)} posts, while assigned post IDs reach ${n(s.max_post_id)}. Those independent signals indicate that most of the historical forum is gone. The museum treats absence as loss, not proof that something never happened.</p><p><a href="#timeline">See the surviving chronology →</a></p></div></section>
 <section class="forum-category"><div class="cat-title">06 · The Interface Time Capsule</div><div class="panel"><h2>phpBB 2.0.6, subSilver, skyLineGrey, Helius</h2><p>The database preserves the forum engine version and style configuration. subSilver was the board default; skyLineGrey and Helius were also installed. Use the style selector above to move between the three historically documented looks. The modern skin is deliberately separate. This build restores the core subSilver gradient cells, forum/topic folder graphics, and mini-post marker from surviving phpBB2 source assets; Helius and skyLineGrey remain configuration-based reconstructions until their exact binary packs can be verified and ingested.</p><p>The preserved phpBB configuration also specifies 20 topics per page and 20 posts per page; this reconstruction now reproduces those original page lengths. The public archive also preserves the community talking about those styles: <a href="#topic/5015">“new board styles” (Nov. 2003)</a> and <a href="#topic/5962">“Which template do you use?” (Jan. 2004)</a>.</p></div></section>
 <section class="forum-category"><div class="cat-title">07 · Lost-and-Found Literature</div><div class="panel"><h2>The archive can return work to its authors</h2><p>Community submissions and forum poetry remain indexed by historical public username or credited author. The reclamation workflow is designed to return one person’s recovered public writing without exposing the raw database or somebody else’s private data.</p><p><a href="#reclaim">Search an old username →</a></p></div></section>
 <section class="forum-category"><div class="cat-title">08 · Beyond the Database</div><div class="panel"><h2>Readers left evidence outside the forum</h2><p>Surviving correspondence documents people returning after years, describing emotional impact, using poems in school and teaching, adapting lines into other media, and tracing their readership back to the early IDP years. Private messages are represented only through anonymized paraphrase.</p><p><a href="#voices">Explore Reader Impact →</a></p></div></section>`
}

function versionHistory(){
 const releases=(V.releases||[]);const milestones=(V.milestones||[]);
 const confirmed=releases.filter(x=>x.status==='confirmed'||x.status==='current').length;
 return `${pageTitle('Build provenance','Version History',`Current public version: v${esc(V.current||CFG.version||'3.9')}. This page distinguishes confirmed release markers from development intervals whose exact numbering cannot be recovered.`)}
 <div class="stats">${stat(releases.length,'version entries')}${stat(confirmed,'confirmed/current markers')}${stat(milestones.length,'documented build milestones')}${stat(V.current||CFG.version||'3.9','current version')}</div>
 <div class="callout"><strong>Why there is a gap:</strong> the repository explicitly records v3.3, the historical README explicitly records v3.4, and the current museum is v3.9. No reliable repository evidence maps individual changes to v3.5, v3.6, v3.7, or v3.8, so those releases are not reconstructed by assumption.</div>
 ${sectionHead('Confirmed release markers','Evidence-backed labels only')}
 <div class="grid">${releases.map(x=>`<article class="card"><div><span class="pill ${x.status==='current'?'gold':''}">v${esc(x.version)}</span><span class="pill">${esc(x.status)}</span></div><h3>${esc(x.title)}</h3><p>${esc(x.summary)}</p><div class="source-note"><strong>Evidence:</strong> ${esc(x.evidence)} • ${esc(x.date)}</div></article>`).join('')}</div>
 ${sectionHead('Build milestones','Repository chronology on September 23, 2026')}
 <div class="timeline">${milestones.map(m=>`<div class="time-item"><strong>${esc(m.time)} · ${esc(m.title)}</strong><div class="small">${esc(m.detail)}</div></div>`).join('')}</div>
 <div class="source-note">Earlier Lovable-side revisions may predate this Git repository. This page records only version evidence that can presently be substantiated.</div>`
}
function about(){return `${pageTitle('Method & ethics','About the reconstruction','What the museum can prove, what it can infer, and what it deliberately refuses to expose.')}<div class="grid"><div class="card"><h3>Two snapshots, one union</h3><p>The earlier backup is stronger for the 2003-2004 community; the later backup preserves later posts and an expanded poetry archive. The museum merges both and retains provenance.</p></div><div class="card"><h3>Historically grounded interface</h3><p>The surviving configuration identifies phpBB 2.0.6, with subSilver as the default style and skyLineGrey plus Helius also installed. It also preserves the original 20-topics-per-page and 20-posts-per-page settings, which the museum reproduces. The subSilver skin now uses surviving phpBB2 gradient and folder/minipost assets; Helius and skyLineGrey remain evidence-backed CSS reconstructions pending exact-pack verification. The modern museum skin remains deliberately separate.</p></div><div class="card"><h3>Privacy by construction</h3><p>No email addresses, IP addresses, password data, or private-message bodies are included in this website’s data files. Reader Impact entries derived from private correspondence are anonymized paraphrases; the original messages remain outside the public museum.</p></div><div class="card"><h3>Text display is reversible</h3><p>The header toggle can repair common mojibake such as â€™ for readability. The original recovered strings remain unchanged in the archive data, and the default display is the original text.</p></div></div>${sectionHead('The scale problem')}<div class="panel"><p>The museum contains <strong>${n(C.meta.stats.posts)}</strong> distinct surviving public posts. The later member post counters total about <strong>${n(C.meta.stats.member_counter_sum)}</strong>, and assigned post IDs reach <strong>${n(C.meta.stats.max_post_id)}</strong>. Those signals support an order-of-magnitude conclusion that the historical board once held roughly one hundred thousand public posts, but they do not produce an exact historical total.</p></div>${sectionHead('Search-bar mystery')}<div class="panel"><p>The huge <code>phpbb_search_wordmatch</code> table in the raw database is a full-text index, not a record of what people typed into the search box. Only a handful of cached search-result rows survive, and they do not preserve the query text. The backups therefore cannot identify or quantify the remembered repeated arbitrary searches.</p></div>${sectionHead('Publishing standard')}<div class="danger-callout callout"><strong>Do not upload the original SQL dumps.</strong> They contain material that does not belong in a public museum. Publish this sanitized reconstruction instead.</div><p class="source-note">Reconstruction date: ${esc(C.meta.built)}. Archive owner: ${esc(CFG.archiveOwner||'IDunnoPoetry')}. <a href="#versions">View version history.</a></p>`}
function missing(thing){return `${pageTitle('Archive gap',thing+' not found')}<div class="empty">That record is not present in the recovered union.</div>`}

function render(){const h0=(location.hash||'#home').slice(1);const qi=h0.indexOf('?');const h=qi<0?h0:h0.slice(0,qi);const parts=h.split('/');const key=parts[0]||'home';let html='';switch(key){case'home':html=home();break;case'forums':html=forums();break;case'forum':html=forum(parts[1],parts[2]);break;case'topic':html=topic(parts[1],parts[2]);break;case'people':html=people();break;case'user':html=user(parts[1],parts[2]);break;case'poetry':html=poetry();break;case'seeds':html=seeds();break;case'verify':html=verification();break;case'documents':html=documents();break;case'document':html=documentView(parts.slice(1).join('/'));break;case'media':html=mediaArchive();break;case'poem':html=poem(parts[1]);break;case'creative':html=creative(parts.slice(1).join('/'));break;case'timeline':html=timeline();break;case'exhibits':html=exhibits();break;case'voices':html=readerImpact();break;case'versions':html=versionHistory();break;case'search':html=search(parts.slice(1).join('/'));break;case'reclaim':html=reclaim(parts.slice(1).join('/'));break;case'about':html=about();break;default:html=missing('Page')}app.innerHTML=html;window.scrollTo(0,0);app.focus({preventScroll:true});if(key==='people')mountPeople();if(key==='poetry')mountPoetry();if(key==='seeds')mountSeeds();if(key==='verify')mountVerification();if(key==='search')mountSearch(parts.slice(1).join('/'));if(key==='reclaim')mountReclaim();const sec=hashParams().get('sec');if(key==='search'&&sec){const el=document.getElementById('sec-'+sec.replace(/[^a-z]/g,''));if(el)el.scrollIntoView()}}
window.addEventListener('hashchange',render);
const skinSelect=document.getElementById('skinSelect');
const skins=['subsilver','skyline','helius','museum'];
function applySkin(name){const skin=skins.includes(name)?name:'subsilver';document.body.classList.remove(...skins.map(x=>'skin-'+x));document.body.classList.add('skin-'+skin);if(skinSelect)skinSelect.value=skin;localStorage.setItem('idpSkin',skin)}
applySkin(localStorage.getItem('idpSkin')||'subsilver');
if(skinSelect)skinSelect.addEventListener('change',()=>applySkin(skinSelect.value));
const textDisplaySelect=document.getElementById('textDisplaySelect');
if(textDisplaySelect){textDisplaySelect.value=textDisplayMode;textDisplaySelect.addEventListener('change',()=>{textDisplayMode=textDisplaySelect.value==='repair'?'repair':'original';localStorage.setItem('idpTextDisplay',textDisplayMode);render()})}
const notice=document.getElementById('notice');if(localStorage.getItem('idpNotice')==='dismissed')notice.style.display='none';document.getElementById('dismissNotice').addEventListener('click',()=>{notice.style.display='none';localStorage.setItem('idpNotice','dismissed')});render();
})();
